cypress_script:
describe('API Endpoint Documentation List', () => {
  it('should display the API documentation with correct title and headings', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('h1').contains('Automation Practice for API Testing');
    cy.get('h2').contains('APIs List for practice');
    cy.get('h2').contains('Subscription');
  });

  it('should not navigate away when clicking an invalid link', () => {
    cy.visit('https://automationexercise.com/api_list');
    cy.get('a[href="#invalid_link"]').click();
    cy.url().should('eq', 'https://automationexercise.com/api_list');
    cy.get('h1').contains('Automation Practice for API Testing');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('API Endpoint Documentation List', () => {
  test('should display the API documentation with correct title and headings', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await expect(page.locator('h1')).toHaveText('Automation Practice for API Testing');
    await expect(page.locator('h2')).toHaveText('APIs List for practice');
    await expect(page.locator('h2')).toHaveText('Subscription');
  });

  test('should not navigate away when clicking an invalid link', async ({ page }) => {
    await page.goto('https://automationexercise.com/api_list');
    await page.click('a[href="#invalid_link"]');
    await expect(page).toHaveURL('https://automationexercise.com/api_list');
    await expect(page.locator('h1')).toHaveText('Automation Practice for API Testing');
  });
});
